export type Produk = {
  id: string;
  nama: string;
  harga: number;
  gambar: string | null;      // API memang bisa mengirim null
  stok: number;
};

export type ResponsDaftar<T> = {
  data: T[];
  halaman: number;
  total: number;
};

const BASE_URL = 'https://api.toko-kita.id';

export async function ambilProduk(halaman = 1): Promise<ResponsDaftar<Produk>> {
  const res = await fetch(`${BASE_URL}/produk?halaman=${halaman}`);

  if (!res.ok) {
    throw new Error(`Gagal memuat produk (${res.status})`);
  }

  // json() mengembalikan any — di sinilah janji itu dibuat
  return (await res.json()) as ResponsDaftar<Produk>;
}

async function minta<T>(path: string, opsi?: RequestInit): Promise<T> {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json' },
    ...opsi,
  });

  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return (await res.json()) as T;
}

// Pemanggilnya menentukan bentuk yang diharapkan:
const daftar = await minta<ResponsDaftar<Produk>>('/produk');
const produk = await minta<Produk>('/produk/p-123');
const pesanan = await minta<Pesanan>('/pesanan', {
  method: 'POST',
  body: JSON.stringify({ produkId: 'p-123', jumlah: 2 }),
});

