type KeadaanMuat<T> =
  | { status: 'memuat' }
  | { status: 'berhasil'; data: T }
  | { status: 'gagal'; pesan: string };

const [keadaan, setKeadaan] = useState<KeadaanMuat<Produk[]>>({ status: 'memuat' });

useEffect(() => {
  let aktif = true;

  ambilProduk()
    .then((hasil) => {
      if (aktif) setKeadaan({ status: 'berhasil', data: hasil.data });
    })
    .catch((e: unknown) => {
      const pesan = e instanceof Error ? e.message : 'Terjadi kesalahan';
      if (aktif) setKeadaan({ status: 'gagal', pesan });
    });

  return () => { aktif = false; };
}, []);

export function LayarProduk() {
  const [keadaan, setKeadaan] = useState<KeadaanMuat<Produk[]>>({ status: 'memuat' });

  if (keadaan.status === 'memuat') {
    return <ActivityIndicator />;
    // keadaan.data ❌ tidak ada di cabang ini — dan memang belum ada
  }

  if (keadaan.status === 'gagal') {
    return <PesanError pesan={keadaan.pesan} onCoba={muatUlang} />;
  }

  // Sampai di sini TypeScript tahu status pasti 'berhasil'
  return (
    <FlatList
      data={keadaan.data}
      keyExtractor={(p) => p.id}
      renderItem={({ item }) => <KartuProduk nama={item.nama} harga={item.harga} />}
    />
  );
}

import AsyncStorage from '@react-native-async-storage/async-storage';

export async function simpan<T>(kunci: string, nilai: T): Promise<void> {
  await AsyncStorage.setItem(kunci, JSON.stringify(nilai));
}

export async function baca<T>(kunci: string, bawaan: T): Promise<T> {
  const mentah = await AsyncStorage.getItem(kunci);   // string | null
  if (mentah === null) return bawaan;

  try {
    return JSON.parse(mentah) as T;
  } catch {
    // isi laci rusak — kembalikan nilai bawaan daripada membiarkan aplikasi crash
    return bawaan;
  }
}

export async function hapus(kunci: string): Promise<void> {
  await AsyncStorage.removeItem(kunci);
}

type KunciSimpanan = 'keranjang' | 'token-login' | 'preferensi-tema';

export async function simpanAman<T>(kunci: KunciSimpanan, nilai: T) {
