import { useEffect, useState } from 'react';
import { baca, simpan } from '../services/simpanan';

export type ItemKeranjang = {
  produkId: string;
  nama: string;
  harga: number;
  jumlah: number;
};

export function useKeranjang() {
  const [items, setItems] = useState<ItemKeranjang[]>([]);
  const [siap, setSiap] = useState(false);

  // muat sekali saat aplikasi dibuka
  useEffect(() => {
    baca<ItemKeranjang[]>('keranjang', []).then((tersimpan) => {
      setItems(tersimpan);
      setSiap(true);
    });
  }, []);

  // simpan setiap kali berubah
  useEffect(() => {
    if (siap) simpan('keranjang', items);
  }, [items, siap]);

  const tambah = (item: ItemKeranjang) => {
    setItems((sebelumnya) => {
      const ada = sebelumnya.find((i) => i.produkId === item.produkId);
      if (!ada) return [...sebelumnya, item];
      return sebelumnya.map((i) =>
        i.produkId === item.produkId ? { ...i, jumlah: i.jumlah + item.jumlah } : i
      );
    });
  };

  const hapusItem = (produkId: string) => {
    setItems((sebelumnya) => sebelumnya.filter((i) => i.produkId !== produkId));
  };

  const total = items.reduce((n, i) => n + i.harga * i.jumlah, 0);

  return { items, tambah, hapusItem, total, siap };
}

